    def _sorted_body(self) -> list[tuple[Key | None, Item]]:
        """The body items reordered so that keys are in alphabetical order.

        Whitespace, comments and ``Null`` placeholders (``k is None``) are
        left in their original positions.
        """
        order = sorted(
            (i for i, (k, _) in enumerate(self._body) if k is not None),
            key=lambda i: self._body[i][0].key,
        )
        used = set(order)
        result: list[tuple[Key | None, Item]] = []
        for i in range(len(self._body)):
            if i in used:
                result.append(self._body[order[used.index(i)]])
            else:
                result.append(self._body[i])

        return result

